  const startIndex = 0;
  const endIndex = 0;
  const hasPrev = false;
  const hasNext = false;

  const goToPage = (_page: number) => {};
  const nextPage = () => {};
  const prevPage = () => {};
  const setPageSize = (_size: number) => {};

  return {
    currentPage, pageSize, totalItems, totalPages,
    startIndex, endIndex, hasPrev, hasNext,
    goToPage, nextPage, prevPage, setPageSize,
  };
}

