import { renderHook, act } from '@testing-library/react';
import { usePagination } from './usePagination';

test('initial state', () => {
  const { result } = renderHook(() => usePagination(100, 10));
  expect(result.current.currentPage).toBe(1);
  expect(result.current.totalPages).toBe(10);
  expect(result.current.startIndex).toBe(0);
  expect(result.current.endIndex).toBe(9);
  expect(result.current.hasPrev).toBe(false);
  expect(result.current.hasNext).toBe(true);
});

test('nextPage advances page', () => {
  const { result } = renderHook(() => usePagination(100, 10));
  act(() => result.current.nextPage());
  expect(result.current.currentPage).toBe(2);
  expect(result.current.startIndex).toBe(10);
  expect(result.current.hasPrev).toBe(true);
});

test('prevPage goes back', () => {
  const { result } = renderHook(() => usePagination(100, 10));
  act(() => result.current.nextPage());
  act(() => result.current.prevPage());
  expect(result.current.currentPage).toBe(1);
});

test('does not go below page 1', () => {
  const { result } = renderHook(() => usePagination(100, 10));
  act(() => result.current.prevPage());
  expect(result.current.currentPage).toBe(1);
});

test('does not exceed total pages', () => {
  const { result } = renderHook(() => usePagination(10, 10));
  act(() => result.current.nextPage());
  expect(result.current.currentPage).toBe(1); // already on last page
});

test('setPageSize recalculates', () => {
  const { result } = renderHook(() => usePagination(100, 10));
  act(() => result.current.setPageSize(25));
  expect(result.current.pageSize).toBe(25);
  expect(result.current.totalPages).toBe(4);
});

test('goToPage jumps to page', () => {
  const { result } = renderHook(() => usePagination(100, 10));
  act(() => result.current.goToPage(5));
  expect(result.current.currentPage).toBe(5);
  expect(result.current.startIndex).toBe(40);
});
